def periods_ok(versions):
    for (start, end), (next_start, _) in zip(versions, versions[1:]):
        if end is None or end != next_start:
            return False
    return versions[-1][1] is None

print(periods_ok([("2026-01-01", "2026-02-01"), ("2026-02-01", "2026-03-01"), ("2026-03-01", None)]))
